-- Somente metadados e política do motor. Sem mensagens, senhas ou desafios.
select jsonb_build_object('functions',(select jsonb_agg(jsonb_build_object('signature',oid::regprocedure::text,'oid',oid,'owner',proowner,'acl',proacl,'definition',pg_get_functiondef(oid))) from pg_proc where oid=any(array['public.whatsapp_pilot_context_allows(uuid,uuid)'::regprocedure,'public.whatsapp_pilot_challenge_allows(uuid,uuid)'::regprocedure,'public.care_cycle_policy_allows(uuid,uuid)'::regprocedure,'public.care_entry_background_allowed(uuid,uuid)'::regprocedure,'public.care_entry_background_queue()'::regprocedure])),
'policy',(select to_jsonb(p) from public.whatsapp_care_cycle_policy p where singleton),'pause',(select to_jsonb(s) from public.whatsapp_send_controls s where scope='global'));
